// One-off bot profile setup (name, descriptions, commands, menu button, avatar).
// Run without deploying: cp scripts/setup.js tgcloud/endpoints/zsetup.js && npm run run -- endpoints/zsetup '{}' --ctx '{initData:{user:{id:0}}}'; rm tgcloud/endpoints/zsetup.js
import { api, InputFile } from 'sdk';
import { WEBAPP_URL, ADMIN_IDS } from '../lib/config.js'; // paths are relative to tgcloud/endpoints/
import { ADMIN_COMMANDS } from '../lib/admin.js';

const AVATAR = '';

function b64(s) {
  const A = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  const clean = s.replace(/=+$/, '');
  const out = new Uint8Array(Math.floor((clean.length * 3) / 4));
  let buf = 0, bits = 0, j = 0;
  for (const ch of clean) {
    buf = (buf << 6) | A.indexOf(ch);
    bits += 6;
    if (bits >= 8) { bits -= 8; out[j++] = (buf >> bits) & 0xff; }
  }
  return out;
}

export default async function (input, ctx) {
  if (ctx.initData?.user?.id !== 0) throw new Error('CLI only');
  const out = {};
  const step = async (name, fn) => {
    try { out[name] = await fn(); } catch (e) { out[name] = 'ERROR: ' + (e.description ?? e.message); }
  };

  await step('name', () => api.setMyName({ name: 'Chth Games 🎲' }));
  // Descriptions in every language (English is also the default for the rest).
  const PROFILE = {
    en: ['🎰 Casino, poker & party games with free play-money chips.\n\n♠️ Texas Hold\'em & video poker\n🎰 Slots, roulette, coinflip, dice\n🃏 Blackjack, mines, hi-lo, crash, plinko\n⚔️ Duels, RPS, jackpot, russian roulette\n🇮🇷 Hokm & Shelem (4 players, 2 teams)\n🎉 Tic-tac-toe, connect four, trivia, hangman\n\nPress Start and play with the buttons, add me to a group, or type @chthgamesbot in any chat. Chips are never cashed out.',
      '♠️ Poker, 🎰 slots, blackjack, crash, duels, trivia & more. Free chips, never cashed out.'],
    fa: ['🎰 بازی‌های کازینو، پوکر و جمعی با چیپ رایگان و بازیچه‌ای.\n\n♠️ تگزاس هولدم و ویدیو پوکر\n🎰 اسلات، رولت، شیر یا خط، تاس\n🃏 بلک‌جک، مین، بالا-پایین، کرش، پلینکو\n⚔️ دوئل، سنگ کاغذ قیچی، جک‌پات، رولت روسی\n🇮🇷 حکم و شلم (۴ نفره، دو تیم)\n🎉 دوز، چهار در یک ردیف، اطلاعات عمومی، جلاد\n\n«شروع» رو بزن و با دکمه‌ها بازی کن، منو به یه گروه اضافه کن، یا توی هر چتی @chthgamesbot رو تایپ کن. چیپ‌ها هیچ‌وقت نقد نمی‌شن.',
      '♠️ پوکر، 🎰 اسلات، بلک‌جک، کرش، دوئل، اطلاعات عمومی و بیشتر. چیپ رایگان، بدون نقد شدن.'],
    ar: ['🎰 ألعاب كازينو وبوكر وألعاب جماعية برقائق لعب مجانية.\n\n♠️ تكساس هولدم وفيديو بوكر\n🎰 ماكينات، روليت، عملة، نرد\n🃏 بلاك جاك، ألغام، أعلى-أدنى، كراش، بلينكو\n⚔️ مبارزات، حجر ورقة مقص، الجائزة الكبرى، الروليت الروسية\n🇮🇷 حكم وشلم (4 لاعبين، فريقان)\n🎉 إكس أو، أربعة في صف، معلومات عامة، الرجل المشنوق\n\nاضغط «ابدأ» والعب بالأزرار، أو أضفني إلى مجموعة، أو اكتب @chthgamesbot في أي محادثة. الرقائق لا تُصرف أبدًا.',
      '♠️ بوكر، 🎰 ماكينات، بلاك جاك، كراش، مبارزات، معلومات عامة والمزيد. رقائق مجانية لا تُصرف.'],
    ru: ['🎰 Казино, покер и игры для компании на бесплатные игровые фишки.\n\n♠️ Техасский холдем и видеопокер\n🎰 Слоты, рулетка, монетка, кубики\n🃏 Блэкджек, мины, выше-ниже, краш, плинко\n⚔️ Дуэли, камень-ножницы-бумага, джекпот, русская рулетка\n🇮🇷 Хокм и Шелем (4 игрока, 2 команды)\n🎉 Крестики-нолики, четыре в ряд, викторина, виселица\n\nНажми «Старт» и играй кнопками, добавь меня в группу или набери @chthgamesbot в любом чате. Фишки не обналичиваются.',
      '♠️ Покер, 🎰 слоты, блэкджек, краш, дуэли, викторина и другое. Бесплатные фишки, без вывода денег.'],
    es: ['🎰 Juegos de casino, póker y de grupo con fichas gratis de mentira.\n\n♠️ Texas Hold\'em y videopóker\n🎰 Tragaperras, ruleta, cara o cruz, dados\n🃏 Blackjack, minas, mayor-menor, crash, plinko\n⚔️ Duelos, piedra-papel-tijera, bote, ruleta rusa\n🇮🇷 Hokm y Shelem (4 jugadores, 2 equipos)\n🎉 Tres en raya, cuatro en línea, trivia, ahorcado\n\nPulsa Iniciar y juega con los botones, añádeme a un grupo o escribe @chthgamesbot en cualquier chat. Las fichas nunca se cobran.',
      '♠️ Póker, 🎰 tragaperras, blackjack, crash, duelos, trivia y más. Fichas gratis, nunca se cobran.'],
  };
  for (const lang of [null, 'en', 'fa', 'ar', 'ru', 'es']) {
    const [description, short_description] = PROFILE[lang ?? 'en'];
    const language_code = lang ?? undefined;
    await step(`description:${lang ?? 'default'}`, () => api.setMyDescription({ description, language_code }));
    await step(`short:${lang ?? 'default'}`, () => api.setMyShortDescription({ short_description, language_code }));
  }

  // Players use the reply keyboard and inline buttons: no command menu for them.
  await step('cmdPrivate', () => api.deleteMyCommands({}));
  await step('cmdGroups', () => api.deleteMyCommands({ scope: { type: 'all_group_chats' } }));
  for (const id of ADMIN_IDS) {
    await step(`cmdAdmin${id}`, () => api.setMyCommands({
      commands: ADMIN_COMMANDS.map(([command, description]) => ({ command, description: `🛠 ${description}` })),
      scope: { type: 'chat', chat_id: id },
    }));
  }
  await step('menuButton', () => api.setChatMenuButton({ menu_button: { type: 'web_app', text: '🎮 Play', web_app: { url: WEBAPP_URL } } }));
  await step('adminRights', () => api.setMyDefaultAdministratorRights({ rights: {
    is_anonymous: false, can_manage_chat: false, can_delete_messages: true, can_manage_video_chats: false,
    can_restrict_members: false, can_promote_members: false, can_change_info: false, can_invite_users: false,
    can_post_stories: false, can_edit_stories: false, can_delete_stories: false,
  } }));
  if (!input.skipPhoto) {
    await step('photo', () => api.setMyProfilePhoto({ photo: { type: 'static', photo: new InputFile(b64(AVATAR), 'avatar.jpg', { type: 'image/jpeg' }) } }));
  }
  out.me = await api.getMe();
  return out;
}
